import{l as a,a as e,c as o,a6 as p}from"./chunks/framework.CVVsdWKy.js";const h=JSON.parse('{"title":"pstack","description":"","frontmatter":{},"headers":[],"relativePath":"ai/skill/pstack.md","filePath":"ai/skill/pstack.md"}'),l={name:"ai/skill/pstack.md"};function s(c,t,i,r,k,d){return e(),o("div",null,[...t[0]||(t[0]=[p('<h1 id="pstack" tabindex="-1">pstack <a class="header-anchor" href="#pstack" aria-label="Permalink to &quot;pstack&quot;">​</a></h1><h2 id="why" tabindex="-1">why <a class="header-anchor" href="#why" aria-label="Permalink to &quot;why&quot;">​</a></h2><p>我们让智能助手干活时，会慢慢得到针对不同任务的多套工作流，后续执行同类型任务时，按匹配的工作流来执行，就能符合预期步骤地完成任务。</p><p>而 pstack 就是预置了多套工作流的技能集合，不用我们自己去探索创建。</p><h2 id="how" tabindex="-1">how <a class="header-anchor" href="#how" aria-label="Permalink to &quot;how&quot;">​</a></h2><p>首先了解 pstack 的工作流程：</p><ol><li>预先准备。通过 <code>/setup-pstack</code> 来配置模型和推理预算，会自动保存配置到本地</li><li>自动选择工作流干活。通过 <code>/poteto-mode &lt;目标&gt; + &lt;完成判据&gt;</code> 或 <code>/poteto-mode &lt;任务&gt;</code> 来干活，其会：匹配工作流 playbook -&gt; 复制 playbook 步骤到 todo -&gt; 每个步骤执行时加载相关技能并让子代理干活（无子代理时可在主会话干活）-&gt; 步骤执行的验证结果 -&gt; 步骤执行完成标记 -&gt; 循环直至所有步骤完成</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>执行创建一个工作流让 Agent 执行时，容易被当成参考而不强制执行。</p><p>而 pstack 让工作流强制生效，是通过：1、TODO 管控；2、步骤间依赖，例如当前步骤依赖上个步骤的执行结果；3、最终回复依赖步骤的结果</p></div><p>在 pi 中如何集成 pstack 呢？</p><ol><li>下载技能包。<a href="https://github.com/backnotprop/pstack" target="_blank" rel="noreferrer">backnotprop/pstack</a> 仓库会自动从 cursor 仓库中同步最新的 pstack 技能包。下载仓库 zip 包</li><li>集成 skills 目录下所有技能到 agent 中</li><li>重启 agent 并执行 <code>/setup-pstack</code></li></ol>',10)])])}const _=a(l,[["render",s]]);export{h as __pageData,_ as default};
